SELECT * FROM (
	SELECT 
	  FROM TBL_NOTIFICATION N
	 WHERE N.RECEIVER_TYPE = '01'
	   AND N.MEMBER_ID = #{memberId}
	 ORDER BY N.NOTIFICATION_ID DESC
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE TBL_NOTIFICATION
   SET IS_READ = 'Y'
 WHERE NOTIFICATION_ID = #{notificationId}
   AND RECEIVER_TYPE = '01'
   AND MEMBER_ID = #{memberId}

mapper.select:
SELECT * FROM (
	SELECT 
	  FROM TBL_NOTIFICATION N
	 WHERE N.RECEIVER_TYPE = '02'
	   AND N.CREATED_AT >= TRUNC(SYSDATE) - #{days}
	 ORDER BY N.NOTIFICATION_ID DESC
) WHERE ROWNUM <= #{limit}

mapper.sql:
 WHERE N.RECEIVER_TYPE = '01'

   AND N.CREATED_AT >= TRUNC(SYSDATE) - #{q.recentDays}


   AND M.MEMBER_NAME LIKE '%' || #{q.name} || '%'


   AND TO_CHAR(N.CREATED_AT, 'YYMMDD') LIKE #{p}


   AND N.NTF_CHANNEL = #{q.channel}


	AND N.SENT_AT IS NULL
	AND N.SENT_AT IS NOT NULL AND N.NTF_CHANNEL = '03'
	AND N.SENT_AT IS NOT NULL AND N.NTF_CHANNEL <> '03'

mapper.select:
SELECT * FROM (
	SELECT , M.MEMBER_NAME, M.PHONE AS MEMBER_PHONE
	  FROM TBL_NOTIFICATION N
	  LEFT JOIN TBL_MEMBER M ON M.MEMBER_ID = N.MEMBER_ID


	   AND N.NOTIFICATION_ID < #{cursor}

	 ORDER BY N.NOTIFICATION_ID DESC
) WHERE ROWNUM <= #{limit}

SELECT COUNT(*) FROM TBL_NOTIFICATION
 WHERE RECEIVER_TYPE = '01' AND NTF_CHANNEL = '03' AND SENT_AT IS NOT NULL
   AND CREATED_AT >= TRUNC(SYSDATE) - #{days}

mapper.update:
UPDATE TBL_NOTIFICATION
   SET SENT_AT = SYSDATE,
       NTF_CHANNEL = #{channel}
 WHERE NOTIFICATION_ID = #{notificationId}
   AND SENT_AT IS NULL
